import os
import sys
import json
import time
from collections import defaultdict

def read_file(file_path):
    try:
        with open(file_path, 'r') as file:
            return file.read()
    except IOError as e:
        print(f"Error: cannot read {file_path}", file=sys.stderr)
        sys.exit(1)

def process_text(text):
    words = text.lower().split()
    word_counts = defaultdict(int)
    for word in words:
        if word.isalnum():
            word_counts[word] += 1
    return word_counts

def get_cache_path():
    return os.path.join(os.path.dirname(sys.argv[0]), 'word_count.cache')

def load_cache():
    try:
        with open(get_cache_path(), 'r') as cache_file:
            return json.load(cache_file)
    except (IOError, json.JSONDecodeError):
        return {}

def save_cache(cache_data):
    with open(get_cache_path(), 'w') as cache_file:
        json.dump(cache_data, cache_file)

def get_file_info(file_path):
    return os.path.abspath(file_path), os.path.getmtime(file_path)

def main():
    if len(sys.argv) != 2:
        print("Usage: python word_count_cache.py <file_path>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]
    file_info = get_file_info(file_path)
    cache = load_cache()

    if file_info in cache:
        print("Using cache", file=sys.stderr)
        word_counts = cache[file_info]
    else:
        text = read_file(file_path)
        word_counts = process_text(text)
        cache[file_info] = word_counts
        print("Cache updated", file=sys.stderr)
        save_cache(cache)

    sorted_counts = sorted(word_counts.items(), key=lambda item: (-item[1], item[0]))
    top_words = sorted_counts[:5]

    for word, count in top_words:
        print(f"{word} {count}")

if __name__ == "__main__":
    main()

