import sys
import os
import re
import json
from collections import defaultdict
import time

def load_cache():
    try:
        with open('word_count.cache', 'r') as f:
            return json.load(f)
    except (IOError, json.JSONDecodeError):
        return {}

def save_cache(cache):
    with open('word_count.cache', 'w') as f:
        json.dump(cache, f)

def process_file(file_path):
    try:
        with open(file_path, 'r') as f:
            text = f.read()
    except IOError:
        print(f"Error: cannot read {file_path}", file=sys.stderr)
        sys.exit(1)

    words = re.findall(r'\b\w+\b', text.lower())
    counts = defaultdict(int)
    for word in words:
        counts[word] += 1

    return file_path, os.path.getmtime(file_path), dict(counts)

def main():
    if len(sys.argv) != 2:
        print("Usage: python word_count_cache.py <file_path>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]
    abs_path = os.path.abspath(file_path)
    cache = load_cache()

    try:
        file_info = cache[abs_path]
    except KeyError:
        file_info = None

    if file_info is not None and file_info[0] == abs_path and file_info[1] == os.path.getmtime(abs_path):
        print("Using cache", file=sys.stderr)
        counts = file_info[2]
    else:
        counts = process_file(file_path)
        cache[abs_path] = (abs_path, os.path.getmtime(file_path), counts)
        print("Cache updated", file=sys.stderr)
        save_cache(cache)

    sorted_counts = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    top_words = sorted_counts[:5]

    for word, count in top_words:
        print(f"{word} {count}")

if __name__ == "__main__":
    main()
